    enum lc3_profile_metric metric)
{
    const struct lc3_profile_stats *stats = &profile->stats[metric];
    uint64_t encode_total =
        profile->stats[LC3_PROFILE_ENCODE_TOTAL].total;
    uint64_t average = stats->count ? stats->total / stats->count : 0;
    uint64_t share_bp = encode_total ?
        stats->total * 10000 / encode_total : 0;
    uint32_t minimum = stats->count ? stats->min : 0;
    uint32_t maximum = stats->count ? stats->max : 0;
    int row = sample_row(metric);

