static inline float xtensa_dot(const int16_t *a, const int16_t *b, int n)
{
    const ae_int16x4 *pa = (const ae_int16x4 *)a;
    const ae_int16x4 *pb = (const ae_int16x4 *)b;
    ae_int64 sum = 0;
    ae_valign align_a = AE_LA64_PP(pa);
    ae_valign align_b = AE_LA64_PP(pb);

    for (int i = 0; i < (n >> 2); i++) {
        ae_int16x4 va, vb;
        AE_LA16X4_IP(va, align_a, pa);
        AE_LA16X4_IP(vb, align_b, pb);
        AE_MULAAAAQ16(sum, va, vb);
    }

    int64_t v = (int64_t)sum;
    int32_t v32 = (v + 32) >> 6;
    return (float)v32;
}

